1	package net.officefloor.hq.app;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	import java.util.Map;
6	import org.springframework.context.annotation.Profile;
7	import org.springframework.jdbc.core.JdbcTemplate;
8	import org.springframework.web.bind.annotation.PostMapping;
9	import org.springframework.web.bind.annotation.RequestBody;
10	import org.springframework.web.bind.annotation.RequestMapping;
11	import org.springframework.web.bind.annotation.RestController;
12	
13	/**
14	 * Per-spec data setup for the harness (DESIGN.md §9). Profile-guarded so it exists ONLY under the
15	 * harness launch (bin/start sets spring.profiles.active=harness) — never in a real deploy. This is
16	 * APP CODE and EVOLVES with the schema (NOT pinned); a change that breaks a prior spec's seed is a
17	 * seed-path regression. Tests call these to ARRANGE data; they ASSERT only through the UI.
18	 *
19	 * <p>{@link #seed} is a plain sequence of one {@code seed*} method per entity. Teaching a new entity
20	 * to the harness is therefore additive: add its {@code seed*} method, call it from {@link #seed},
21	 * and add its {@code TRUNCATE} to {@link #reset} — no existing entity's code is touched.
22	 */
23	@Profile("harness")
24	@RestController
25	@RequestMapping("/__test__")
26	public class TestSupportController {
27	
28	    private final Audit audit;
29	    private final JdbcTemplate jdbc;
30	
31	    public TestSupportController(Audit audit, JdbcTemplate jdbc) {
32	        this.audit = audit;
33	        this.jdbc = jdbc;
34	    }
35	
36	    /** Truncate all domain tables and clear the audit file so each spec starts clean. */
37	    @PostMapping("/reset")
38	    public void reset() {
39	        audit.clear();
40	        // Referential integrity is dropped for the duration so the tables can be truncated (and
41	        // their identity counters restarted) regardless of FK order (e.g. projects -> clients).
42	        jdbc.execute("SET REFERENTIAL_INTEGRITY FALSE");
43	        for (String table : List.of("dashboard_clock", "notes", "project_tags", "tags", "tasks",
44	                "payments", "line_items", "invoices", "contacts", "projects", "clients")) {
45	            jdbc.execute("TRUNCATE TABLE " + table + " RESTART IDENTITY");
46	        }
47	        jdbc.execute("SET REFERENTIAL_INTEGRITY TRUE");
48	    }
49	
50	    /** Insert the fixture a spec needs; each entity is seeded by its own {@code seed*} method. */
51	    @PostMapping("/seed")
52	    public void seed(@RequestBody Map<String, Object> fixture) {
53	        seedClients(fixture);
54	        seedProjects(fixture);
55	        seedContacts(fixture);
56	        seedInvoices(fixture);
57	        seedPayments(fixture);
58	        seedTasks(fixture);
59	        seedTags(fixture);
60	        seedNotes(fixture);
61	        seedProjectTags(fixture);
62	        seedClock(fixture);
63	    }
64	
65	    private void seedClock(Map<String, Object> fixture) {
66	        // The dashboard's fixed "as of" reference date (top-level asOf), if the fixture supplies one.
67	        Object asOf = fixture.get("asOf");
68	        if (asOf != null) {
69	            jdbc.update("INSERT INTO dashboard_clock (id, as_of) VALUES (1, ?)", asOf.toString());
70	        }
71	    }
72	
73	    private void seedClients(Map<String, Object> fixture) {
74	        for (Map<String, Object> c : rows(fixture, "clients")) {
75	            jdbc.update("INSERT INTO clients (id, name, email) VALUES (?, ?, ?)",
76	                    id(c, "id"), c.get("name"), c.get("email"));
77	        }
78	    }
79	
80	    private void seedProjects(Map<String, Object> fixture) {
81	        for (Map<String, Object> p : rows(fixture, "projects")) {
82	            // status defaults to ACTIVE so a fixture that omits it gets an active project; archived
83	            // defaults to FALSE (the table default) unless the fixture pins it.
84	            new Insert("projects")
85	                    .set("id", id(p, "id"))
86	                    .set("name", p.get("name"))
87	                    .set("client_id", id(p, "clientId"))
88	                    .set("status", p.get("status") == null ? "ACTIVE" : p.get("status").toString())
89	                    .setIfPresent("archived", p.get("archived"))
90	                    .setIfPresent("budget", asDouble(p.get("budget")))
91	                    .run();
92	        }
93	    }
94	
95	    private void seedContacts(Map<String, Object> fixture) {
96	        for (Map<String, Object> ct : rows(fixture, "contacts")) {
97	            jdbc.update(
98	                    "INSERT INTO contacts (id, client_id, name, email, role, is_primary)"
99	                            + " VALUES (?, ?, ?, ?, ?, ?)",
100	                    id(ct, "id"), id(ct, "clientId"), ct.get("name"), ct.get("email"),
101	                    ct.get("role"), Boolean.TRUE.equals(ct.get("primary")));
102	        }
103	    }
104	
105	    private void seedInvoices(Map<String, Object> fixture) {
106	        for (Map<String, Object> in : rows(fixture, "invoices")) {
107	            // Insert only the columns the fixture supplies, so the table's own defaults apply when a
108	            // fixture omits them (a plain null would trip the NOT NULL columns). status defaults to
109	            // DRAFT and amount defaults to 0 — an invoice's amount is derived from its line items,
110	            // so fixtures list lineItems rather than a single typed amount.
111	            new Insert("invoices")
112	                    .set("id", id(in, "id"))
113	                    .set("project_id", id(in, "projectId"))
114	                    .set("status", in.get("status") == null ? "DRAFT" : in.get("status").toString())
115	                    .setIfPresent("amount", asDouble(in.get("amount")))
116	                    .setIfPresent("issued_date", asText(in.get("issuedDate")))
117	                    .setIfPresent("due_date", asText(in.get("dueDate")))
118	                    .run();
119	            seedLineItems(in);
120	        }
121	    }
122	
123	    private void seedLineItems(Map<String, Object> invoice) {
124	        long invoiceId = id(invoice, "id");
125	        for (Map<String, Object> li : rows(invoice, "lineItems")) {
126	            jdbc.update(
127	                    "INSERT INTO line_items (id, invoice_id, description, qty, unit_price)"
128	                            + " VALUES (?, ?, ?, ?, ?)",
129	                    id(li, "id"), invoiceId, li.get("description"),
130	                    ((Number) li.get("qty")).intValue(),
131	                    ((Number) li.get("unitPrice")).doubleValue());
132	        }
133	    }
134	
135	    private void seedPayments(Map<String, Object> fixture) {
136	        List<Map<String, Object>> payments = rows(fixture, "payments");
137	        for (Map<String, Object> p : payments) {
138	            jdbc.update(
139	                    "INSERT INTO payments (id, invoice_id, amount, paid_date) VALUES (?, ?, ?, ?)",
140	                    id(p, "id"), id(p, "invoiceId"), asDouble(p.get("amount")),
141	                    asText(p.get("date")));
142	        }
143	        if (!payments.isEmpty()) {
144	            // Seeding explicit ids does not advance H2's identity counter, so bump it past the
145	            // seeded rows or the app's next generated payment id would collide with a fixture id.
146	            Long next = jdbc.queryForObject("SELECT MAX(id) + 1 FROM payments", Long.class);
147	            jdbc.execute("ALTER TABLE payments ALTER COLUMN id RESTART WITH " + next);
148	        }
149	    }
150	
151	    private void seedTasks(Map<String, Object> fixture) {
152	        for (Map<String, Object> t : rows(fixture, "tasks")) {
153	            jdbc.update("INSERT INTO tasks (id, project_id, title, done) VALUES (?, ?, ?, ?)",
154	                    id(t, "id"), id(t, "projectId"), t.get("title"),
155	                    Boolean.TRUE.equals(t.get("done")));
156	        }
157	    }
158	
159	    private void seedTags(Map<String, Object> fixture) {
160	        for (Map<String, Object> tg : rows(fixture, "tags")) {
161	            jdbc.update("INSERT INTO tags (id, name) VALUES (?, ?)", id(tg, "id"), tg.get("name"));
162	        }
163	    }
164	
165	    private void seedNotes(Map<String, Object> fixture) {
166	        List<Map<String, Object>> notes = rows(fixture, "notes");
167	        for (Map<String, Object> n : notes) {
168	            jdbc.update(
169	                    "INSERT INTO notes (id, target_type, target_id, text, created_at)"
170	                            + " VALUES (?, ?, ?, ?, ?)",
171	                    id(n, "id"), n.get("targetType"), id(n, "targetId"), n.get("text"),
172	                    n.get("at").toString());
173	        }
174	        if (!notes.isEmpty()) {
175	            // Seeding explicit ids does not advance H2's identity counter, so bump it past the
176	            // seeded rows or the app's next generated note id would collide with a fixture id.
177	            Long next = jdbc.queryForObject("SELECT MAX(id) + 1 FROM notes", Long.class);
178	            jdbc.execute("ALTER TABLE notes ALTER COLUMN id RESTART WITH " + next);
179	        }
180	    }
181	
182	    private void seedProjectTags(Map<String, Object> fixture) {
183	        for (Map<String, Object> pt : rows(fixture, "projectTags")) {
184	            jdbc.update("INSERT INTO project_tags (project_id, tag_id) VALUES (?, ?)",
185	                    id(pt, "projectId"), id(pt, "tagId"));
186	        }
187	    }
188	
189	    /** The list of fixture rows under {@code key}, or an empty list when the fixture omits it. */
190	    @SuppressWarnings("unchecked")
191	    private static List<Map<String, Object>> rows(Map<String, Object> fixture, String key) {
192	        return (List<Map<String, Object>>) fixture.getOrDefault(key, List.of());
193	    }
194	
195	    /** A fixture id column: JSON numbers arrive as {@link Number}, the tables use {@code BIGINT}. */
196	    private static long id(Map<String, Object> row, String key) {
197	        return ((Number) row.get(key)).longValue();
198	    }
199	
200	    private static Double asDouble(Object value) {
201	        return value == null ? null : ((Number) value).doubleValue();
202	    }
203	
204	    private static String asText(Object value) {
205	        return value == null ? null : value.toString();
206	    }
207	
208	    /**
209	     * Builds an {@code INSERT} whose column set is decided per row, so a fixture can omit a column
210	     * and let the table's own default apply (a bare null would trip a NOT NULL column). Required
211	     * columns are added with {@link #set}; optional ones with {@link #setIfPresent}.
212	     */
213	    private final class Insert {
214	        private final String table;
215	        private final StringBuilder cols = new StringBuilder();
216	        private final StringBuilder marks = new StringBuilder();
217	        private final List<Object> args = new ArrayList<>();
218	
219	        Insert(String table) {
220	            this.table = table;
221	        }
222	
223	        Insert set(String column, Object value) {
224	            if (cols.length() > 0) {
225	                cols.append(", ");
226	                marks.append(", ");
227	            }
228	            cols.append(column);
229	            marks.append("?");
230	            args.add(value);
231	            return this;
232	        }
233	
234	        Insert setIfPresent(String column, Object value) {
235	            return value == null ? this : set(column, value);
236	        }
237	
238	        void run() {
239	            jdbc.update("INSERT INTO " + table + " (" + cols + ") VALUES (" + marks + ")",
240	                    args.toArray());
241	        }
242	    }
243	}
244

